import java.util.List;
import java.util.ArrayList;

// One physical room, identified by id, with a fixed type that drives pricing
class Room {
    private String id;   // e.g. "D1"
    private String type; // "SINGLE", "DOUBLE", or "SUITE"

    Room(String id, String type) {
        this.id = id;
        this.type = type;
    }

    String getId() {
        return id; // simple accessor
    }

    String getType() {
        return type; // simple accessor
    }
}

// Factory pattern: builds a full room inventory from just three counts,
// instead of every caller manually constructing each Room by hand
class RoomFactory {
    static List<Room> createRooms(int singleCount, int doubleCount, int suiteCount) {
        List<Room> rooms = new ArrayList<>();
        for (int i = 1; i <= singleCount; i++) {
            rooms.add(new Room("S" + i, "SINGLE")); // S1, S2, ...
        }
        for (int i = 1; i <= doubleCount; i++) {
            rooms.add(new Room("D" + i, "DOUBLE")); // D1, D2, ...
        }
        for (int i = 1; i <= suiteCount; i++) {
            rooms.add(new Room("U" + i, "SUITE")); // U1, U2, ... (U for suite, D already taken)
        }
        return rooms; // hand back the fully assembled inventory
    }
}

