// Strategy pattern: the reservation service does not care HOW a room's
// nightly price is decided, only that calling getPricePerNight(type) returns a number
interface RoomPricingStrategy {
    double getPricePerNight(String roomType);
}

// Concrete strategy: a fixed nightly rate per room type
class StandardRoomPricingStrategy implements RoomPricingStrategy {
    @Override
    public double getPricePerNight(String roomType) {
        if (roomType.equals("SUITE")) return 300.0;  // suites cost the most
        if (roomType.equals("DOUBLE")) return 150.0; // doubles cost the middle rate
        return 100.0;                                // single rooms cost the base rate
    }
}

