import java.util.Map;
import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;

// Observer pattern: anything that wants to react to a reservation outcome implements this
interface ReservationObserver {
    void onReservationConfirmed(String reservationId, String roomId, String guestName, double totalPrice);
    void onReservationRejected(String roomId, String guestName, String reason);
}

// One concrete observer: simply prints every reservation outcome to the console
class ConsoleReservationObserver implements ReservationObserver {
    @Override
    public void onReservationConfirmed(String reservationId, String roomId, String guestName, double totalPrice) {
        // report the reservation id, room, guest, and total price
        System.out.println("Reservation " + reservationId + " confirmed for " + roomId + ", guest " + guestName + ", total: " + totalPrice);
    }

    @Override
    public void onReservationRejected(String roomId, String guestName, String reason) {
        // report which room and guest, and exactly why it was rejected
        System.out.println("Reservation rejected for " + roomId + ", guest " + guestName + ": " + reason);
    }
}

// Orchestrates room lookup, date-range overlap checking, pricing, and confirmation
public class HotelReservationService {
    private Map<String, Room> rooms;                    // room id -> that room
    private List<Reservation> reservations;              // every confirmed reservation, across all rooms
    private RoomPricingStrategy pricingStrategy;         // however nightly prices are decided
    private List<ReservationObserver> observers = new ArrayList<>(); // everyone watching for outcomes
    private int reservationCounter = 0;                  // used to generate readable reservation ids

    public HotelReservationService(List<Room> roomList, RoomPricingStrategy pricingStrategy) {
        this.rooms = new HashMap<>();
        for (Room room : roomList) {
            rooms.put(room.getId(), room); // index every room by id
        }
        this.reservations = new ArrayList<>();
        this.pricingStrategy = pricingStrategy;
    }

    public void addObserver(ReservationObserver observer) {
        observers.add(observer); // register a new observer, does not replace existing ones
    }

    // True only if NO existing reservation for this room overlaps [checkIn, checkOut).
    // Two ranges [a, b) and [c, d) overlap exactly when a < d AND c < b,
    // this correctly allows back-to-back stays (one checkout day equals the next checkin day)
    public boolean isRoomAvailable(String roomId, int checkIn, int checkOut) {
        for (Reservation reservation : reservations) {
            if (reservation.getRoomId().equals(roomId)) {
                boolean overlaps = checkIn < reservation.getCheckOutDay() && reservation.getCheckInDay() < checkOut;
                if (overlaps) {
                    return false; // this existing reservation blocks the requested range
                }
            }
        }
        return true; // scanned every reservation for this room, nothing overlapped
    }

    // Attempts to book roomId for guestName across [checkIn, checkOut).
    // Returns the new reservation id on success, or null if the booking failed
    public String bookRoom(String roomId, String guestName, int checkIn, int checkOut) {
        Room room = rooms.get(roomId);
        if (room == null) {
            notifyRejected(roomId, guestName, "Room does not exist");
            return null;
        }

        if (checkIn >= checkOut) {
            notifyRejected(roomId, guestName, "Check-in must be strictly before check-out");
            return null; // a zero or negative-length stay makes no sense
        }

        if (!isRoomAvailable(roomId, checkIn, checkOut)) {
            notifyRejected(roomId, guestName, "Room not available for these dates");
            return null; // some existing reservation genuinely overlaps this range
        }

        int nights = checkOut-checkIn; // exactly how many nights this stay covers
        double totalPrice = pricingStrategy.getPricePerNight(room.getType()) * nights;

        reservationCounter++;
        String reservationId = "RES-" + reservationCounter;
        reservations.add(new Reservation(reservationId, roomId, guestName, checkIn, checkOut));

        for (ReservationObserver observer : observers) {
            observer.onReservationConfirmed(reservationId, roomId, guestName, totalPrice);
        }
        return reservationId; // hand the new reservation id back to the caller
    }

    private void notifyRejected(String roomId, String guestName, String reason) {
        for (ReservationObserver observer : observers) {
            observer.onReservationRejected(roomId, guestName, reason);
        }
    }
}

