    def on_reservation_confirmed(self, reservation_id, room_id, guest_name, total_price):
        print(f"Reservation {reservation_id} confirmed for {room_id}, guest {guest_name}, total: {total_price}")

    def on_reservation_rejected(self, room_id, guest_name, reason):
        print(f"Reservation rejected for {room_id}, guest {guest_name}: {reason}")


class HotelReservationService:
    def __init__(self, room_list, pricing_strategy):
        self.rooms = {}
        for room in room_list:
            self.rooms[room.id] = room
        self.reservations = []
        self.pricing_strategy = pricing_strategy
        self.observers = []
        self.reservation_counter = 0

    def add_observer(self, observer):
        self.observers.append(observer)

    def is_room_available(self, room_id, check_in, check_out):
        for reservation in self.reservations:
            if reservation.room_id == room_id:
                overlaps = check_in < reservation.check_out_day and reservation.check_in_day < check_out
                if overlaps:
                    return False
        return True

    def book_room(self, room_id, guest_name, check_in, check_out):
        room = self.rooms.get(room_id)
        if room is None:
            self._notify_rejected(room_id, guest_name, "Room does not exist")
            return None

        if check_in >= check_out:
            self._notify_rejected(room_id, guest_name, "Check-in must be strictly before check-out")
            return None

        if not self.is_room_available(room_id, check_in, check_out):
            self._notify_rejected(room_id, guest_name, "Room not available for these dates")
            return None

        nights = check_out-check_in
        total_price = self.pricing_strategy.get_price_per_night(room.type) * nights

        self.reservation_counter += 1
        reservation_id = f"RES-{self.reservation_counter}"
        self.reservations.append(Reservation(reservation_id, room_id, guest_name, check_in, check_out))

        for listener in self.observers:
            listener.on_reservation_confirmed(reservation_id, room_id, guest_name, total_price)
        return reservation_id

    def _notify_rejected(self, room_id, guest_name, reason):
        for listener in self.observers:
            listener.on_reservation_rejected(room_id, guest_name, reason)


