#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

class Room {
public:
    string id;
    string type;

    Room(string id, string type) : id(id), type(type) {}
};

class RoomFactory {
public:
    static vector<Room> createRooms(int singleCount, int doubleCount, int suiteCount) {
        vector<Room> rooms;
        for (int i = 1; i <= singleCount; i++) {
            rooms.push_back(Room("S" + to_string(i), "SINGLE"));
        }
        for (int i = 1; i <= doubleCount; i++) {
            rooms.push_back(Room("D" + to_string(i), "DOUBLE"));
        }
        for (int i = 1; i <= suiteCount; i++) {
            rooms.push_back(Room("U" + to_string(i), "SUITE"));
        }
        return rooms;
    }
};

class RoomPricingStrategy {
public:
    virtual double getPricePerNight(string roomType) = 0;
    virtual ~RoomPricingStrategy() {}
};

class StandardRoomPricingStrategy : public RoomPricingStrategy {
public:
    double getPricePerNight(string roomType) override {
        if (roomType == "SUITE") return 300.0;
        if (roomType == "DOUBLE") return 150.0;
        return 100.0;
    }
};

class Reservation {
public:
    string id;
    string roomId;
    string guestName;
    int checkInDay;
    int checkOutDay;

    Reservation(string id, string roomId, string guestName, int checkInDay, int checkOutDay)
        : id(id), roomId(roomId), guestName(guestName), checkInDay(checkInDay), checkOutDay(checkOutDay) {}
};

class ReservationObserver {
public:
    virtual void onReservationConfirmed(string reservationId, string roomId, string guestName, double totalPrice) = 0;
    virtual void onReservationRejected(string roomId, string guestName, string reason) = 0;
    virtual ~ReservationObserver() {}
};

class ConsoleReservationObserver : public ReservationObserver {
public:
    void onReservationConfirmed(string reservationId, string roomId, string guestName, double totalPrice) override {
        cout << "Reservation " << reservationId << " confirmed for " << roomId << ", guest " << guestName << ", total: " << totalPrice << endl;
    }

    void onReservationRejected(string roomId, string guestName, string reason) override {
        cout << "Reservation rejected for " << roomId << ", guest " << guestName << ": " << reason << endl;
    }
};

class HotelReservationService {
private:
    unordered_map<string, Room> rooms;
    vector<Reservation> reservations;
    RoomPricingStrategy* pricingStrategy;
    vector<ReservationObserver*> observers;
    int reservationCounter;

    void notifyRejected(string roomId, string guestName, string reason) {
        for (auto listener : observers) {
            listener->onReservationRejected(roomId, guestName, reason);
        }
    }

public:
    HotelReservationService(vector<Room> roomList, RoomPricingStrategy* pricingStrategy)
        : pricingStrategy(pricingStrategy), reservationCounter(0) {
        for (auto& room : roomList) {
            rooms.insert({room.id, room});
        }
    }

    void addObserver(ReservationObserver* observer) {
        observers.push_back(observer);
    }

    bool isRoomAvailable(string roomId, int checkIn, int checkOut) {
        for (auto& reservation : reservations) {
            if (reservation.roomId == roomId) {
                bool overlaps = checkIn < reservation.checkOutDay && reservation.checkInDay < checkOut;
                if (overlaps) return false;
            }
        }
        return true;
    }

    string bookRoom(string roomId, string guestName, int checkIn, int checkOut) {
        auto it = rooms.find(roomId);
        if (it == rooms.end()) {
            notifyRejected(roomId, guestName, "Room does not exist");
            return "";
        }
        Room& room = it->second;

        if (checkIn >= checkOut) {
            notifyRejected(roomId, guestName, "Check-in must be strictly before check-out");
            return "";
        }

        if (!isRoomAvailable(roomId, checkIn, checkOut)) {
            notifyRejected(roomId, guestName, "Room not available for these dates");
            return "";
        }

        int nights = checkOut-checkIn;
        double totalPrice = pricingStrategy->getPricePerNight(room.type) * nights;

        reservationCounter++;
        string reservationId = "RES-" + to_string(reservationCounter);
        reservations.push_back(Reservation(reservationId, roomId, guestName, checkIn, checkOut));

        for (auto listener : observers) {
            listener->onReservationConfirmed(reservationId, roomId, guestName, totalPrice);
        }
        return reservationId;
    }
};

int main() {
    // Factory pattern builds the room inventory: 0 single, 1 double, 0 suite
    vector<Room> roomList = RoomFactory::createRooms(0, 1, 0); // just D1

    StandardRoomPricingStrategy pricing;
    HotelReservationService service(roomList, &pricing);
    ConsoleReservationObserver observer;
    service.addObserver(&observer); // print every outcome

    service.bookRoom("D1", "Alice", 1, 5); // days 1-5, no conflicts, succeeds
    service.bookRoom("D1", "Bob", 3, 7);   // overlaps Alice's stay, rejected
    service.bookRoom("D1", "Carol", 5, 8); // starts exactly when Alice leaves, succeeds

    return 0;
}
